python3 -c "import os, pathlib, re, textwrap; tgt=os.environ['TARGET_DIR'];
# ---- edit autogen/oai/client.py ----
client_path=pathlib.Path(tgt)/'autogen/oai/client.py'; src=client_path.read_text();
if '_detect_tool_support' not in src:
    src=re.sub(r'(class OpenAIWrapper:.*?\n)',
        lambda m: m.group(1)+'\n'+textwrap.dedent('''
    def _detect_tool_support(self, model_name: str) -> bool:
        """Detect if a model supports OpenAI tool calling protocol.
        Heuristic: models containing "gpt-4" or "gpt-3.5" are assumed to support tool calls.
        Users can also explicitly set "supports_tool_calls" in the config.
        """
        if not model_name:
            return False
        name=model_name.lower()
        return any(k in name for k in ("gpt-4","gpt-3.5"))
    '''), src, flags=re.DOTALL);
if 'self.supports_tool_calls' not in src:
    src=re.sub(r'(self\._clients = \[self\._client\(config, openai_config\) for config in config_list\])',
        lambda m: m.group(1)+'\n        # ENHANCED_V1: Detect tool call support based on model name or explicit flag\n        first_cfg = config_list[0] if config_list else base_config\n        model_name = first_cfg.get("model") if isinstance(first_cfg, dict) else None\n        explicit = first_cfg.get("supports_tool_calls") if isinstance(first_cfg, dict) else None\n        self.supports_tool_calls = explicit if explicit is not None else self._detect_tool_support(model_name)', src);
client_path.write_text(src);
# ---- edit autogen/agentchat/conversable_agent.py ----
conv_path=pathlib.Path(tgt)/'autogen/agentchat/conversable_agent.py'; src2=conv_path.read_text();
# Insert filtering before client.create call inside generate_oai_reply
pattern=r'(response = client\.create\(\n\s*context=messages\[-1\]\.pop\("context", None\), messages=self\._oai_system_message \+ all_messages\n\s*\))';
if re.search(pattern, src2, flags=re.DOTALL):
    replacement=textwrap.dedent('''
        # ENHANCED_V1: Remove tool_responses from payload if model does not support tool calls
        if not self.client.supports_tool_calls:
            filtered = []
            for msg in all_messages:
                if "tool_responses" in msg:
                    msg = {k: v for k, v in msg.items() if k != "tool_responses"}
                filtered.append(msg)
            all_messages = filtered
        response = client.create(
            context=messages[-1].pop("context", None), messages=self._oai_system_message + all_messages
        )
    ''');
    src2=re.sub(pattern, replacement, src2, flags=re.DOTALL);
conv_path.write_text(src2);
print('Edits applied')"

